={{ JSON.stringify({ 
  question: $('Unpack brief').item.json.recipe_run.question,
  family: $('Unpack brief').item.json.recipe_run.brief.style_guess.value,
  target_abv: $('Unpack brief').item.json.recipe_run.brief.targets.abv,
  sensory: $('Unpack brief').item.json.recipe_run.brief.sensory,
  candidates: $('Find closest BJCP style').all().map(({ json: c }) =>
    `- id ${c.ref_style_id} | ${c.label} | score ${c.score} | ABV ${c.abv_range ?? "not defined"} (${c.abv_fit ?? "no target"})\n` +
    `  matched: ${JSON.stringify(c.matched)}\n` +
    `  description: ${c.overall_impression}`
  ).join("\n")
}) }}

